import glob, yaml
rows=[]
for f in glob.glob('/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/inbox/local/items/*.yaml'):
    d=yaml.safe_load(open(f))
    if d.get('status')=='open': rows.append(d)
for d in sorted(rows, key=lambda r: r['id']):
    prov=(d.get('metadata') or {}).get('provenance') or {}
    print(f"{d['id']} | {d['kind']:12} | {str(d.get('audience'))[:20]:21} | run={prov.get('run')} {str(prov.get('role'))[:9]:10} | {str(d.get('created_at'))[:16]} | {(d.get('body') or '').split(chr(10))[0][:62]}")
EOF

